import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../providers/global/wallets_provider.dart';
import '../../themes/stack_colors.dart';
import '../../utilities/clipboard_interface.dart';
import '../../utilities/constants.dart';
import '../../utilities/text_styles.dart';
import '../../utilities/util.dart';
import '../../wallets/wallet/wallet_mixin_interfaces/slatepack_interface.dart';
import '../../widgets/background.dart';
import '../../widgets/conditional_parent.dart';
import '../../widgets/custom_buttons/app_bar_icon_button.dart';
import '../../widgets/desktop/primary_button.dart';
import 'slatepack_import_flow.dart';
import 'slatepack_input_field.dart';

/// The "Slatepack" screen: takes any slatepack and hands it to
/// [SlatepackImportFlow], which works out whether to receive or finalize.
class SlatepackView extends ConsumerStatefulWidget {
  const SlatepackView({
    super.key,
    required this.walletId,
    this.clipboard = const ClipboardWrapper(),
  });

  static const String routeName = "/slatepackView";

  final String walletId;
  final ClipboardInterface clipboard;

  @override
  ConsumerState<SlatepackView> createState() => _SlatepackViewState();
}

class _SlatepackViewState extends ConsumerState<SlatepackView> {
  late final TextEditingController _controller;
  late final FocusNode _focusNode;
  late final SlatepackInterface _wallet;

  /// True while a slatepack is being imported, so a second press of Continue
  /// cannot start the import again.
  bool _importing = false;

  bool get _hasText => _controller.text.trim().isNotEmpty;

  Future<void> _continuePressed() async {
    if (_importing) return;
    setState(() => _importing = true);
    try {
      if (!Util.isDesktop && _focusNode.hasFocus) {
        _focusNode.unfocus();
        await Future<void>.delayed(const Duration(milliseconds: 75));
      }
      if (!mounted) return;

      final done = await SlatepackImportFlow.run(
        context: context,
        wallet: _wallet,
        text: _controller.text,
      );
      if (done && mounted) {
        setState(() => _controller.text = "");
      }
    } finally {
      _importing = false;
      if (mounted) setState(() {});
    }
  }

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController();
    _focusNode = FocusNode();
    _wallet =
        ref.read(pWallets).getWallet(widget.walletId) as SlatepackInterface;
  }

  @override
  void dispose() {
    _controller.dispose();
    _focusNode.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    debugPrint("BUILD: $runtimeType");
    final terms = _wallet.slatepackTerms;

    return ConditionalParent(
      condition: !Util.isDesktop,
      builder: (child) => Background(
        child: Scaffold(
          backgroundColor: Theme.of(context)
              .extension<StackColors>()!
              .background,
          appBar: AppBar(
            leading: AppBarBackButton(
              onPressed: () {
                Navigator.of(context).pop();
              },
            ),
            title: Text("Slatepack", style: STextStyles.navBarTitle(context)),
          ),
          body: SafeArea(
            child: LayoutBuilder(
              builder: (context, constraints) {
                return SingleChildScrollView(
                  child: ConstrainedBox(
                    constraints: BoxConstraints(
                      minHeight: constraints.maxHeight,
                    ),
                    child: IntrinsicHeight(
                      child: Padding(
                        padding: EdgeInsets.symmetric(
                          horizontal: Constants.size.standardPadding,
                        ),
                        child: child,
                      ),
                    ),
                  ),
                );
              },
            ),
          ),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            "Paste, scan or open a ${terms.noun} you were sent. It is "
            "received or finalized depending on what it is.",
            style: Util.isDesktop
                ? STextStyles.desktopTextExtraSmall(context).copyWith(
                    color: Theme.of(context)
                        .extension<StackColors>()!
                        .textSubtitle1,
                  )
                : STextStyles.label(context),
          ),
          const SizedBox(height: 12),
          SlatepackInputField(
            controller: _controller,
            focusNode: _focusNode,
            hint: "Enter ${terms.payload}",
            clipboard: widget.clipboard,
            onChanged: (_) => setState(() {}),
          ),
          Util.isDesktop ? const SizedBox(height: 24) : const Spacer(),
          PrimaryButton(
            label: "Continue",
            buttonHeight: Util.isDesktop ? ButtonHeight.l : null,
            enabled: _hasText && !_importing,
            onPressed: _hasText && !_importing ? _continuePressed : null,
          ),
          if (!Util.isDesktop) SizedBox(height: Constants.size.standardPadding),
        ],
      ),
    );
  }
}
